{
  "states": ["STABLE", "CHANGING", "UNSTABLE"],
  "transitions": [
    {
      "from": "STABLE",
      "event": "rcv Confirm R",
      "action": "ignore",
      "to": "STABLE"
    },
    {
      "from": "STABLE",
      "event": "app/protocol evt",
      "action": "snd Change L",
      "to": "CHANGING"
    },
    {
      "from": "STABLE",
      "event": "rcv non-ack",
      "action": "snd Change L",
      "to": "STABLE"
    },
    {
      "from": "CHANGING",
      "event": "rcv Change R",
      "action": "calc new value, snd Confirm L",
      "to": "STABLE"
    },
    {
      "from": "CHANGING",
      "event": "rcv empty Confirm R",
      "action": "revert to old value",
      "to": "STABLE"
    },
    {
      "from": "CHANGING",
      "event": "rcv Confirm R",
      "action": "if valid set F.value, set F.state := STABLE",
      "to": "STABLE"
    },
    {
      "from": "CHANGING",
      "event": "pref list changes",
      "action": "transition to UNSTABLE",
      "to": "UNSTABLE"
    },
    {
      "from": "UNSTABLE",
      "event": "snd Change L",
      "action": "transition back to CHANGING",
      "to": "CHANGING"
    }
  ]
}

{
  "states": ["REQUEST", "PARTOPEN", "RESPOND", "OPEN", "CLOSEREQ", "CLOSING"],
  "transitions": [
    {
      "from": "REQUEST",
      "event": "Response",
      "action": "Move to PARTOPEN state, set PARTOPEN timer",
      "to": "PARTOPEN"
    },
    {
      "from": "RESPOND",
      "event": "Request",
      "action": "Send Response, possibly with Init Cookie; destroy socket if Init Cookie sent",
      "to": "RESPOND"
    },
    {
      "from": "RESPOND",
      "event": "Other valid packet types",
      "action": "Set S.OSR to P.seqno, move to OPEN",
      "to": "OPEN"
    },
    {
      "from": "PARTOPEN",
      "event": "Response",
      "action": "Send Ack",
      "to": "PARTOPEN"
    },
    {
      "from": "PARTOPEN",
      "event": "P.type != Sync",
      "action": "Set S.OSR to P.seqno, move to OPEN",
      "to": "OPEN"
    },
    {
      "from": "CLOSEREQ",
      "event": "CloseReq",
      "action": "Generate Close, move to CLOSING",
      "to": "CLOSING"
    }
  ]
}

